create or replace function public.current_access_context() returns jsonb language sql stable security definer set search_path=public as $$ select jsonb_build_object('organization_id',m.organization_id,'organization_name',o.name,'organization_slug',o.slug,'plan_code',o.plan_code,'organization_status',o.status,'trial_ends_at',o.trial_ends_at,'user_id',p.id,'full_name',p.full_name,'email',p.email,'role',m.role,'status',m.status,'permissions',case when m.role='owner' then public.role_permissions_json('owner') else public.role_permissions_json(m.role)||coalesce(m.permissions,'{}'::jsonb) end) from public.organization_members m join public.organizations o on o.id=m.organization_id join public.profiles p on p.id=m.user_id where m.user_id=auth.uid() and m.organization_id=public.current_organization_id() and m.status='active' limit 1 $$;